pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure the id is not already scheduled (to avoid false positive reverts)
        vm.assume(!c.isOperation(id));

        // cancel should revert because operation is not pending
