pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt) public {
        // Only proposer can schedule
        vm.assume(c.hasRole(c.PROPOSER_ROLE(), address(this)));
        vm.assume(c.hasRole(c.EXECUTOR_ROLE(), address(this)));

        // Schedule an operation
        c.schedule(target, value, data, predecessor, salt, c.getMinDelay());
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Check operation is pending
        assertTrue(c.isOperationPending(id), "should be pending before cancel");

        // Cancel the operation
        c.cancel(id);

        // After cancel, operation should NOT be pending
        assertTrue(!c.isOperationPending(id), "should not be pending after cancel");
    }
}

