pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(address caller, bytes32 id) public {
        // Ensure caller is not the zero address to avoid edge cases
        vm.assume(caller != address(0));

        // First, schedule an operation as the proposer (address(this) has PROPOSER_ROLE)
        // We need to know the operation id. Use a simple dummy operation.
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(uint256(1));
        bytes32 operationId = c.hashOperation(target, value, data, predecessor, salt);

        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, 1 days);

        // Now try to cancel with the caller
        vm.prank(caller);
        // Check if caller has PROPOSER_ROLE in the original contract
        // For the reference, this should be true only for address(this) (and itself, but that's not the caller)
        // Since we deployed with address(this) as proposer, only address(this) should succeed
        bool expectedSuccess = c.hasRole(c.PROPOSER_ROLE(), caller);

        // Attempt cancellation
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.cancel.selector, operationId));

        // For the reference contract: cancellation succeeds iff caller has PROPOSER_ROLE
        // For the mutant (hasRole always false), cancellation will always revert (since onlyRole modifier fails)
        // So the rule is: success == expectedSuccess
        if (expectedSuccess) {
            assertTrue(success, "Expected cancel to succeed for proposer");
        } else {
            assertTrue(!success, "Expected cancel to revert for non-proposer");
        }
    }
}

