pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // The property: if isOperationPending(id) returns false (i.e., id is DONE or never scheduled), then cancel(id) must revert.
        // In the reference, isOperationPending returns getTimestamp(id) > 1, so for a done op (timestamp == 1) it returns false (good).
        // In the mutant, isOperationPending returns getTimestamp(id) >= 1, so for a done op (timestamp == 1) it returns true (bad).
        // We will schedule an operation, then execute it (making its timestamp become _DONE_TIMESTAMP = 1), then try to cancel.
        // Ensure we have proposer role (already have from setup).
        vm.assume(id != bytes32(0)); // avoid trivial? Not needed but OK.
        // Schedule a dummy operation (no call, just salt).
        address target = address(0);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = id;
        uint256 delay = 0;
        c.schedule(target, value, data, predecessor, salt, delay);
        // Get the operation hash.
        bytes32 opId = c.hashOperation(target, value, data, predecessor, salt);
        // Execute the operation (needs executor role; we have it).
        c.execute{value: 0}(target, value, data, predecessor, salt);
        // Now the operation is done (timestamp == 1). In reference, isOperationPending(opId) is false.
        bool pending = c.isOperationPending(opId);
        // Try to cancel; should revert if not pending.
        (bool ok,) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", opId));
        // General rule: If pending is false, then cancel should revert (ok should be false).
        assertTrue(!pending == !ok, "Rule: cancel should succeed only when operation is pending");
    }
}

