contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id, uint256 timestampBlock, uint256 timestampGet) public {
        vm.assume(timestampBlock >= 1);
        vm.assume(timestampGet >= 0);
        // Set block.timestamp
        vm.warp(timestampBlock);
        // Set the timestamp for the operation id
