        bool revertCancel;
        try c.cancel(id) {
            revertCancel = false;
        } catch {
            revertCancel = true;
        }
        // The rule: if operation was successfully cancelled, then isOperationReady must have returned false.
        // Because cancel only succeeds if operation isPending (timestamp > 1) and after cancel, operation is not Done.
